    "diag.title": "Diagnosis — your language health check",
    "diag.subtitle": "Adaptive: right answers step the questions up a level, wrong answers step down. Then two short listening items and two reading items at your band — the items rotate every run, so a re-check measures growth, not memory. About 10 minutes.",
    "diag.introBefore": "Most learners study blind for months. This check estimates your JLPT section scores — language knowledge, reading, listening, each /60 against the ",
