    "diag.honestLimits": "Honest limits: this is an in-app estimate from a short adaptive sample, not an official score. JLPT publishes no official vocab lists, so level pools are community estimates. Use it to aim your study — the mock exams and the real exam are the proof.",
    "diag.sinceLast": "Since your last check",
