    "diag.deltaNote": "Same short check, measured the same way — the movement is the trend your Twin and your Coach letter use. Estimates, as always, not official scores.",
    "diag.prescriptionTitle": "Your next 2 weeks",
    "diag.prescriptionSub": "Prepared by Saki, your planner — from this checkup and your problem",
    "diag.rx.weakest": "Days 1–14, daily: 15 minutes on your weakest section — {section} ({score}/60 vs the 19/60 survival line). Nothing else matters until this is safe.",
    "diag.rx.voice": "Daily: one Voice Loop scene out loud, repeat to mastery. Speaking is trained even though JLPT doesn’t test it — your job and BJT life do.",
    "diag.rx.anki": "Daily: review queue, max 10 new cards. When the queue feels heavy, do fewer new — never skip review days entirely.",
    "diag.rx.bjt": "3× per week: BJT trainer (listening + document). Your proof target needs business Japanese, not just JLPT Japanese.",
    "diag.rx.commute": "Commute: shadowing mode, 10 minutes, material you already understood once. Listening plays ONCE in the real exam — train that way.",
