    // ── round 2 (i18n completion, 2026-11-07): promise / ladder / fleet / loop stats / voice / session / legacy / resume ──
    "promise.life.cityOffice": "Handle one real city-office, hospital or school visit entirely alone — rehearsed here first",
    "promise.life.workMeeting": "Carry your own part of one real work meeting fully in Japanese, keigo included",
    "promise.life.conversation": "Hold a 10-minute unscripted conversation with a Japanese speaker, without switching to English",
    "promise.life.jobInterview": "Walk into one real job interview and answer in Japanese without a script",
    "promise.life.fullDay": "Handle one full day of real life — errands, counters, calls — entirely in Japanese",
    "promise.height.nextLevel": "Pass {next} (JLPT {passMark}/180, every section ≥ {sectionMin}/60)",
    "promise.height.n1Margin": "N1 with real margin — mocks at {target}+/180 — plus: {life}",
    "promise.height.rescue": "{level} secured — pass mark {passMark}/180 with margin, {weakestLabel} rescued — plus: {life}",
    "promise.reason.baseAt": "Your checkup estimates you at {level} with {total}/180 — already at/above the {level} pass mark ({passMark}), so {level} is treated as your base, not your ceiling.",
    "promise.reason.baseWithin": "Your checkup estimates you at {level} with {total}/180 — within {gap} points of the {level} pass mark ({passMark}), so {level} is treated as your base, not your ceiling.",
    "promise.reason.strength": "No section is under the {sectionMin}/60 survival line (weakest: {weakestLabel} {weakestScore}/60) and your strongest section is {strongest}/60 — that strength is a latent base that transfers upward when the input is pitched one level up.",
    "promise.reason.nextRung": "So the honest 60-day height is the next rung, {next} — trained at {next} for technique, with input from {next} and above, and sat only when practice mocks clear it with margin.",
    "promise.reason.belowLine": "Your checkup estimates {level} at {total}/180, but {weakestLabel} is {weakestScore}/60 — under the {sectionMin}/60 survival line. One section under the line fails the whole exam, so the next level is NOT the honest promise yet; rescuing this section is.",
    "promise.reason.gap": "Your checkup estimates {total}/180 against the {level} pass mark of {passMark} — a gap of {gap} points. Sixty days closes that gap at this level far more reliably than it buys the next level as well, so this level, secured with margin, is the honest promise.",
    "promise.reason.noStrength": "Your checkup estimates {level} at {total}/180 with {weakestLabel} weakest at {weakestScore}/60 and no section showing the 36+/60 latent strength that makes a level jump realistic in 60 days — so this level, secured, is the honest promise.",
    "promise.reason.lifeProof": "And because exam dates are only twice a year, the height includes one you can prove any week: {life}.",
    "promise.bjt.maxed": "Business side: your BJT estimate (~{score}) is already in J1+ territory — the 60 days defend it with timed BJT training.",
