    "promise.plan.dailyNext": "Daily: the One Session — one scene, your cards, one listening bite, all pitched at {next}.",
    "promise.plan.weakestFirst": "Weakest first: {weakestLabel} ({weakestScore}/60) gets the extra 15 minutes until it is safely over 30/60 in practice.",
    "promise.plan.mocksNext": "Day 30 and Day 55: timed {next} mocks. Day-60 rule: book the real {next} only if mocks sit ≥ {target}/180 with every section ≥ 30/60 — margin, not luck.",
    "promise.plan.dailyRescue": "Daily: the One Session, pitched at {level} — with {weakestLabel} first until it clears 30/60 in practice (safe margin over the {sectionMin}/60 line).",
    "promise.plan.rehearse": "Rehearse the real-life height in the Voice Loop at least 3× per week, then do it for real once before Day 60.",
    "promise.plan.mocksRescue": "Day 30: timed {level} mock, target ≥ {target10}/180. Day 55: target ≥ {target15}/180 with every section ≥ 30/60 — then book, or re-run the diagnosis and let it re-promise honestly.",
    "promise.honesty": "This height is computed from the latent base your diagnosis actually found — a resident re-climbing a level they once held moves faster than a first-time learner at the same score, and a weaker base gets a rescue height, not a fantasy. Timelines depend on that base and on the daily sessions actually happening; the Day-30/Day-55 mock gates are how we check the promise is on track.",
