    "reader.fixSayLine": "Ce mot n'est pas arrivé jusqu'à ta lecture. Redis sa phrase une fois de plus : 「{sentence}」",
    "reader.footerDeclared": "Adapté au {band} que tu m'as indiqué et à ta file : environ {pct} % de ses mots devraient déjà t'être familiers (une estimation) · {words}\nTon bilan dans Yonde affine tout ça quand tu veux.",
    "reader.footerDiagnosis": "Adapté à ton niveau {band} et à ta file : environ {pct} % de ses mots devraient déjà t'être familiers (une estimation) · {words}",
    "reader.footerQueue": "Adapté à ta file : environ {pct} % de ses mots devraient déjà t'être familiers (une estimation) · {words}\nLe niveau N4 est un choix doux par défaut — fais le bilan de 10 minutes dans Yonde et je m'adapterai à ton vrai niveau.",
    "reader.guestAfter": " mots — ta file, ton niveau. Connecte-toi et Hori pourra creuser pour toi ; un invité n'a pas de mots auxquels s'adapter, alors il n'y a honnêtement rien à montrer pour l'instant.",
    "reader.guestBefore": "Le Lecteur adapte chaque texte à ",
    "reader.guestYour": "tes",
    "reader.intro": "Un court texte mesuré par rapport aux mots que tu connais vraiment — la même étagère que Hori sert dans Telegram, adaptée avec les mêmes règles. Les mots nouveaux sont en gras ; un seul appui les mine dans ta file unique.",
