    "reader.oneFixTitle": "Une Correction De Nao",
    "reader.readAloudButton": "Lire À Voix Haute",
    "reader.readAloudIntro": "Lis le texte à voix haute et ton navigateur transforme ta voix en texte — la reconnaissance vocale gratuite intégrée à des navigateurs comme Chrome. Yonde lui-même n'envoie rien nulle part : la comparaison se fait ici, dans le code, et seul ton score est gardé. ",
    "reader.readAloudIntroEmphasis": "C'est une comparaison de lecture, pas une note de prononciation.",
    "reader.readAloudTitle": "Lis-Le À Voix Haute",
