    "reader.recogStopped": "La reconnaissance vocale s'est arrêtée avant d'entendre une lecture complète — rien n'a été noté. Réessaie dans un endroit plus calme.",
    "reader.recycledBatch": "\nCelui-ci entraîne le lot que tu apprends en ce moment — les mêmes mots, dans de nouvelles phrases, jusqu'à ce qu'ils soient à toi.",
    "reader.starterFooter": "Un texte de démarrage, pas un choix adapté — je ne connais pas encore ton niveau, alors celui-ci vient de l'étagère facile, avec peu de mots nouveaux. Mine les mots que tu veux : chaque mot miné m'apprend ce que tu connais. Fais le bilan de 10 minutes dans Yonde et l'adaptation s'active — à partir de là, chaque texte est mesuré par rapport à tes mots avant d'être envoyé.",
