    "diag.title": "Diagnostic — votre bilan de santé linguistique",
    "diag.subtitle": "Adaptatif : les bonnes réponses font monter les questions d’un niveau, les erreurs les font descendre. Puis deux courts exercices d’écoute et deux de lecture à votre niveau — les items changent à chaque passage, donc un nouveau bilan mesure la progression, pas la mémoire. Environ 10 minutes.",
    "diag.introBefore": "La plupart des apprenants étudient à l’aveugle pendant des mois. Ce bilan estime vos scores par section au JLPT — connaissances de la langue, lecture, écoute, chacun sur 60 par rapport à la ",
    "diag.introLine": "ligne de survie des 19/60",
