    "diag.poolDeckFail": "Le jeu de mots n’a pas pu être chargé sur cet appareil, donc le bilan ne peut pas commencer. Vérifiez votre connexion et réessayez — rien n’a été enregistré.",
    "diag.poolShort": "Le jeu de mots s’est épuisé en cours de route, donc le score de langue repose sur moins de mots que d’habitude. L’écoute et la lecture ne sont pas affectées.",
