    "diag.summaryAbove": "au niveau ou au-dessus de la ligne sur le papier, mais ne passez l’examen que lorsque les examens blancs le dépassent de 15 à 20 points avec de la marge dans CHAQUE section.",
    "diag.summaryBelow": "il vous faut +{need} points modélisés, et les points les moins chers sont dans {weakest}.",
