    "promise.honesty": "この高さは、診断が実際に見つけた潜在的な土台から計算しています。かつて到達したレベルを登り直す居住者は、同じスコアの初学者より速く進み、土台が弱ければ救済の高さが設定されます。幻想ではありません。期間はその土台と、毎日のセッションが実際に行われるかどうかに依存します。30日目と55日目の模試ゲートが、約束が順調かを確認する方法です。",
